          <label className="text-xs font-semibold">Maximum score<input required type="number" min="0.01" step="0.01" value={continuousForm.max_score} onChange={e=>setContinuousForm(v=>({...v,max_score:e.target.value}))} className="mt-1 w-full rounded-lg border p-2.5"/></label>
